def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if budget <= 0:
        return 0

    units = supply / WATER_REQ
    scarcity = units <= 2.05
    very_scarce = units <= 1.2

    prev_bids = []
    dangerous_prev = []
    rich_live = []
    for oid, opp in alive:
        if opp.get('budget', 0) > DAILY_SALARY * 1.2:
            rich_live.append((oid, opp))
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('budget', 0) > 0 and opp.get('hp', 0) > 0:
                dangerous_prev.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    live_pressure = max(dangerous_prev) if dangerous_prev else highest_prev

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water >= 2:
        urgency += 3
    elif no_water >= 1:
        urgency += 1
    if very_scarce:
        urgency += 2
    elif scarcity:
        urgency += 1
    if day >= 8:
        urgency += 1

    if not alive:
        if urgency >= 3:
            return min(budget, 35)
        return min(budget, 8)

    if urgency >= 5:
        target = max(92.0, live_pressure + 2.0)
    elif urgency >= 3:
        if live_pressure >= 95:
            target = 96.0
        else:
            target = max(58.0, live_pressure + 1.5)
    else:
        if not scarcity:
            if live_pressure >= 120:
                target = 6.0
            elif live_pressure >= 95:
                target = 12.0
            else:
                target = 18.0
        else:
            if live_pressure >= 120:
                target = 26.0
            elif live_pressure >= 95:
                target = 34.0
            else:
                target = max(28.0, live_pressure * 0.55)

    if len(rich_live) >= 2 and urgency <= 2 and live_pressure >= 100:
        target = min(target, 10.0 if not scarcity else 24.0)

    reserve = 0.0
    if hp <= 4 or no_water >= 1:
        reserve = 0.0
    elif day <= 6:
        reserve = 40.0
    else:
        reserve = 20.0

    affordable = max(0.0, budget - reserve)
    bid = min(target, budget)
    if affordable > 0:
        bid = min(bid, max(affordable, min(budget, 8.0 if urgency <= 2 else target)))

    if urgency >= 4 and budget >= 90:
        bid = max(bid, min(budget, max(90.0, live_pressure + 2.0)))

    if bid < 0:
        bid = 0
    if bid > budget:
        bid = budget
    return bid

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return float(min(my_status['budget'], 20))
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_prev = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 80
    if my_status['hp'] <= 3:
        return float(min(my_status['budget'], max(avg_prev * 1.2, 90)))
    return float(min(my_status['budget'], max(avg_prev * 0.95, 75)))
